mapper.select:
SELECT a.AREA_DSCR, as INDEX_VALUE FROM visual_screen.vs_growth_public_budget a WHERE 1 = 1 and a.area_dscr is not null and a.INDEX_NAME = #{params.INDEX_NAME} AND a.AREA_CODE <> '500000'
${params.whereInfo}
and a.PERIOD_FLAG = #{params.PERIOD_FLAG}
group by a.area_dscr order by desc limit 10

SELECT a.AREA_DSCR, AS GROWTH_INDEX_VALUE FROM visual_screen.vs_growth_public_budget a left join visual_screen.vs_growth_public_budget a1 ON a1.DACCT = AND a.AREA_CODE = a1.AREA_CODE AND a1.AREA_CODE <> '500000' and a1.INDEX_NAME = #{params.INDEX_NAME} WHERE 1 = 1 and a.area_dscr is not null and a.INDEX_NAME = #{params.INDEX_NAME} AND a.AREA_CODE <> '500000'
${params.whereInfo}
and a.PERIOD_FLAG = #{params.PERIOD_FLAG}
group by a.AREA_DSCR order by desc limit 10

