${params.whereInfo}
and a.PERIOD_FLAG = #{params.PERIOD_FLAG}
group by a.area_dscr order by desc limit 10

SELECT a.AREA_DSCR, as GROWTH_INDEX_VALUE FROM visual_screen.vs_budget_revenue a LEFT JOIN visual_screen.vs_budget_revenue a1 ON a1.DACCT = AND a.AREA_CODE = a1.AREA_CODE AND a1.AREA_CODE <> '500000' and a1.INDEX_NAME = #{params.INDEX_NAME} WHERE 1 = 1 and a.area_dscr is not null and a.INDEX_NAME = #{params.INDEX_NAME} AND a.AREA_CODE <> '500000'
${params.whereInfo}
and a.PERIOD_FLAG = #{params.PERIOD_FLAG}
group by a.AREA_DSCR order by desc limit 10

SELECT a.AREA_DSCR, as INDEX_VALUE FROM visual_screen.vs_amount_ranking_by_region a WHERE 1 = 1 and a.area_dscr is not null
${params.whereInfo}
and PERIOD_FLAG = #{params.PERIOD_FLAG}
group by area_dscr order by desc limit 10

SELECT rownum
FROM (
    SELECT ROW_NUMBER() OVER (ORDER BY SUM(COALESCE(a.INDEX_VALUE, 0))) AS rownum, a.area_dscr
    FROM visual_screen.vs_amount_ranking_by_region a
    WHERE 1 = 1 and a.area_dscr is not null

        ${params.whereInfo}


        and PERIOD_FLAG = #{params.PERIOD_FLAG}

    GROUP BY a.area_dscr
) c
WHERE area_dscr = '重庆'

SELECT a.AREA_DSCR, as INDEX_VALUE FROM visual_screen.vs_amount_ranking_by_region a WHERE 1 = 1 and a.area_dscr is not null
${params.whereInfo}
and PERIOD_FLAG = #{params.PERIOD_FLAG}
group by area_dscr order by desc limit 10

SELECT a.AREA_DSCR, as INDEX_VALUE
FROM visual_screen.vs_regional_taxation a WHERE 1 = 1 and a.area_dscr is not null
${params.whereInfo}
and a.PERIOD_FLAG = #{params.PERIOD_FLAG}
group by a.AREA_DSCR order by desc limit 10

SELECT a.AREA_DSCR, as INDEX_VALUE FROM visual_screen.vs_regional_taxation a WHERE 1 = 1 and a.AREA_DSCR is not null
${params.whereInfo}
and PERIOD_FLAG = #{params.PERIOD_FLAG}
group by a.AREA_DSCR order by desc limit 10

SELECT a.AREA_DSCR, ROUND(COALESCE(SUM(COALESCE(a.INDEX_VALUE_1, 0)) / ${params.unit}, 0), 2) as INDEX_VALUE, COALESCE(ROUND(((SUM(COALESCE(a.INDEX_VALUE_1, 0)) - SUM(COALESCE(a.GROWTH_INDEX_VALUE_1, 0))) / NULLIF(SUM(COALESCE(a.GROWTH_INDEX_VALUE_1, 0)), 0)) * 100, 2), 0) as GROWTH_INDEX_VALUE, as INDEX_VALUE1, as GROWTH_INDEX_VALUE1 FROM visual_screen.vs_five_provinces_in_southwest_china a WHERE 1 = 1 and a.AREA_DSCR is not null
${params.whereInfo}
and PERIOD_FLAG = #{params.PERIOD_FLAG}
group by a.AREA_DSCR order by a.INDEX_VALUE_1 desc

SELECT a.AREA_DSCR, ROUND(COALESCE(SUM(COALESCE(a.INDEX_VALUE_1, 0)) / ${params.unit}, 0), 2) as INDEX_VALUE, COALESCE(ROUND(((SUM(COALESCE(a.INDEX_VALUE_1, 0)) - SUM(COALESCE(a.GROWTH_INDEX_VALUE_1, 0))) / NULLIF(SUM(COALESCE(a.GROWTH_INDEX_VALUE_1, 0)), 0)) * 100, 2), 0) as GROWTH_INDEX_VALUE, as INDEX_VALUE1, as GROWTH_INDEX_VALUE1 FROM visual_screen.vs_municipalities_directly a WHERE 1 = 1 and area_dscr is not null
${params.whereInfo}
and PERIOD_FLAG = #{params.PERIOD_FLAG}
group by AREA_DSCR order by a.INDEX_VALUE_1 desc

